/**
* Entity state flags
*/
var EntityState = /* @__PURE__ */ function(EntityState) {
	/** Static entity (does not move) */
	EntityState[EntityState["Static"] = 1] = "Static";
	/** Dynamic entity (affected by forces) */
	EntityState[EntityState["Dynamic"] = 2] = "Dynamic";
	/** Sleeping entity (inactive, not updated) */
	EntityState[EntityState["Sleeping"] = 4] = "Sleeping";
	/** Kinematic entity (moved manually, but can collide) */
	EntityState[EntityState["Kinematic"] = 8] = "Kinematic";
	return EntityState;
}({});
